#!/usr/bin/env bash
#
# Finalize the July 2 2026 Spark spell USDS/sUSDS withdrawals (Base / Optimism / Unichain
# -> Ethereum ALM Proxy 0x1601843c5E9bC251A3272907010AFa41Fa18347E), plus the three 10k USDS
# test withdrawals proven Jul 2.
#
# Safe to run repeatedly: each entry is skipped unless it is proven, its dispute game has
# resolved DEFENDER_WINS, both delays have passed, it is not yet finalized, and an eth_call
# simulation from the prover succeeds. Only then does it send.
#
# Must be signed by the prover 0x62B5262D3639eA5A8ec0D8Aa442f1135ecF77205
# (finalizeWithdrawalTransaction looks up the proof under msg.sender).
#
# Expected earliest finalization (UTC):
#   base-10k-USDS   Jul  3 16:37:24  (finalizable now)
#   op-10k-USDS     Jul  9 17:15:24
#   uni-10k-USDS    Jul  9 17:15:48
#   base-USDS/sUSDS Jul  7 19:51:24
#   op-USDS/sUSDS   Jul 13 19:52:12
#   uni-USDS/sUSDS  Jul 13 19:52:36
#
set -uo pipefail

PROVER=0x62B5262D3639eA5A8ec0D8Aa442f1135ecF77205
RPC="$MAINNET_RPC_URL"
ccall() { env -u ETH_KEYSTORE -u ETH_FROM cast call "$@" --rpc-url "$RPC"; }

process() {
  local label=$1 portal=$2 whash=$3 cd_hex=$4
  echo "=== $label"
  if [ "$(ccall $portal 'finalizedWithdrawals(bytes32)(bool)' $whash)" = "true" ]; then
    echo "    already finalized — skip"; return; fi
  local res game provenTs
  res=$(ccall $portal 'provenWithdrawals(bytes32,address)(address,uint64)' $whash $PROVER)
  game=$(echo "$res" | sed -n 1p); provenTs=$(echo "$res" | sed -n 2p | awk '{print $1}')
  if [ "$provenTs" = "0" ]; then echo "    NOT PROVEN under $PROVER — investigate"; return; fi
  local status resolvedAt
  status=$(ccall $game 'status()(uint8)')
  resolvedAt=$(ccall $game 'resolvedAt()(uint64)' | awk '{print $1}')
  if [ "$status" != "2" ]; then echo "    dispute game $game not resolved DEFENDER_WINS yet (status=$status) — skip"; return; fi
  local maturity finality proofReady gameReady ready now
  maturity=$(ccall $portal 'proofMaturityDelaySeconds()(uint256)' | awk '{print $1}')
  finality=$(ccall $portal 'disputeGameFinalityDelaySeconds()(uint256)' | awk '{print $1}')
  proofReady=$((provenTs + maturity)); gameReady=$((resolvedAt + finality))
  ready=$(( (proofReady > gameReady ? proofReady : gameReady) + 1 ))
  now=$(date +%s)
  if [ "$now" -lt "$ready" ]; then
    echo "    finalizable at $(date -u -r $ready '+%b %d %H:%M:%S UTC') — skip"; return; fi
  if ! env -u ETH_KEYSTORE -u ETH_FROM cast call $portal $cd_hex --from $PROVER --rpc-url "$RPC" > /dev/null; then
    echo "    SIMULATION FAILED — investigate before sending"; return; fi
  echo "    simulation OK — sending finalize tx"
  cast send $portal $cd_hex --rpc-url "$RPC"
}

